param([string]$CaseId='', [string]$ManifestName='m78-closure-v1.json', [switch]$ReuseCaseObjects, [switch]$OmitMap)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$base='http://192.168.122.1:8872';$root='C:\JudasValidation';$m=$null
function Upload($p,$n){for($attempt=0;$attempt -lt 10;$attempt++){try{Invoke-WebRequest -UseBasicParsing "$base/$n" -Method Post -InFile $p|Out-Null;return}catch{if($attempt -eq 9){throw};Start-Sleep -Milliseconds 200}}}
try{
$m=(Invoke-WebRequest -UseBasicParsing "$base/$ManifestName").Content|ConvertFrom-Json;$s=$m.scratch;$o=$m.output;$c=@($m.cases|Where-Object {$_.id -eq $CaseId});if($c.Count -ne 1){throw 'Named unique prepared case required'};$c=$c[0]
$engine=[IO.File]::ReadAllText("$o\m78-closure-engine.json")|ConvertFrom-Json;if((Get-FileHash $engine.archive.path).Hash.ToLower() -ne $engine.archive.sha256){throw 'Frozen archive changed'}
foreach($u in $engine.objects){if((Get-FileHash $u.path).Hash.ToLower() -ne $u.sha256){throw 'Final replacement object changed'}}
$exe="$root\Build\Release\m78-closure-$CaseId.exe";if(Test-Path $exe){throw 'Preserve existing closure output'};if((Get-PSDrive C).Free -lt 11MB){throw 'Insufficient exact case headroom'}
Import-Module "$root\VS2022\Common7\Tools\Microsoft.VisualStudio.DevShell.dll";Enter-VsDevShell -VsInstallPath "$root\VS2022" -SkipAutomaticLocation -DevCmdArguments '-arch=x64 -host_arch=x64';Set-Location "$root\Build";$objs=@();$rows=@()
foreach($u in $c.inputs){$obj="$s\objects\$($u.objectName)";if((Test-Path $obj) -and !$ReuseCaseObjects){throw 'Preserve previous case object'};if($ReuseCaseObjects -and (!$u.reuseOriginal -or !(Test-Path $obj))){throw 'Retry only existing frozen verified reused objects'}
 if($u.reuseOriginal){if(!$ReuseCaseObjects){Invoke-WebRequest -UseBasicParsing $u.objectURL -OutFile $obj};if((Get-FileHash $obj).Hash.ToLower() -ne $u.originalObjectSHA256){throw 'Frozen reused object changed'}}else{
 $src=Join-Path "$s\source" $u.path;if((Get-FileHash $src).Hash.ToLower() -ne $u.sha256){throw 'Current fixture source changed'};$flags=[string]$c.compilerFlags;$flags=[regex]::Replace($flags,'/Fo"[^"]*"',('/Fo"'+$obj+'"'),'IgnoreCase');$flags=[regex]::Replace($flags,'/Fd"[^"]*"',('/Fd"'+$s+'\objects\case.pdb"'),'IgnoreCase');$flags='/I"'+$s+'\source\third_party" /I"'+$s+'\source" /I"'+$s+'\source\src" /I"'+$m.oldSource+'\src" /I"'+$root+'\Source" /I"'+$root+'\Source\tests" '+$flags+' "'+$src+'"';$rsp="$s\objects\$($u.objectName).rsp";[IO.File]::WriteAllText($rsp,$flags,[Text.UTF8Encoding]::new($false));$log="$o\m78-closure-$CaseId-$($u.objectName)-compile.log";$ErrorActionPreference='Continue';& cl.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$exit=$LASTEXITCODE;$ErrorActionPreference='Stop';Upload $log ([IO.Path]::GetFileName($log));if($exit -ne 0){throw 'Fresh fixture compile failed'}
 }
 $objs+=$obj;$rows+=@{path=$obj;name=[IO.Path]::GetFileName($obj);bytes=(Get-Item $obj).Length;sha256=(Get-FileHash $obj).Hash.ToLower();source=$u.path;sourceSHA256=$u.sha256;reuseOriginal=$u.reuseOriginal}
}
$link=[string]$c.linkFlags;$link=[regex]::Replace($link,'/OUT:"[^"]*"',('/OUT:"'+$exe+'"'),'IgnoreCase');$replacement=(($engine.objects|ForEach-Object {'"'+$_.path+'"'})-join ' ')+' "'+$engine.archive.path+'"';$link=[regex]::Replace($link,'RELEASE\\JUDAS_ENGINE\.LIB','','IgnoreCase');$link=$replacement+' '+$link;$link=[regex]::Replace($link,'/PDB:"[^"]*"',('/PDB:"'+$s+'\objects\case-link.pdb"'),'IgnoreCase');$link=[regex]::Replace($link,'/IMPLIB:"[^"]*"',('/IMPLIB:"'+$s+'\objects\case.lib"'),'IgnoreCase');foreach($a in $objs){$link+=' "'+$a+'"'};$map="$o\m78-closure-$CaseId.map";if(!$OmitMap){$link+=' /MAP:"'+$map+'"'};$link+=' /VERBOSE:LIB';$rsp="$s\objects\$CaseId-link.rsp";[IO.File]::WriteAllText($rsp,$link,[Text.UTF8Encoding]::new($false));$log="$o\m78-closure-$CaseId-link.log";$ErrorActionPreference='Continue';& link.exe "@$rsp" 2>&1|Tee-Object -FilePath $log;$exit=$LASTEXITCODE;$ErrorActionPreference='Stop';Upload $log ([IO.Path]::GetFileName($log));if($exit -ne 0){throw 'Final explicit-object link failed'};if(!$OmitMap){Upload $map ([IO.Path]::GetFileName($map))};if([IO.File]::ReadAllText($log) -match '(?im)^\s*Loaded\s+.*judas_engine\.lib\([^\)\r\n]*(PhysicsWorld|WorldPersistence)\.obj\)'){throw 'Unexpected frozen replaced member extracted'}
$env:GALLIUM_DRIVER='llvmpipe';$env:JUDAS_ENGINE_ROOT="$root\Source";$env:TEMP="$o\temp";$env:TMP=$env:TEMP;$env:APPDATA="$o\userdata\Roaming";$env:LOCALAPPDATA="$o\userdata\Local";New-Item -ItemType Directory $env:TEMP,$env:APPDATA,$env:LOCALAPPDATA -Force|Out-Null
foreach($n in @('M78_DIAGNOSTIC_PERSIST_DRIVE_IMPULSES','JUDAS_DIAGNOSTIC_RESTORE_DRIVES','JUDAS_BOUNDARY_REPLAY_CAPTURED_NATIVE','JUDAS_BOUNDARY_REPLAY_MODE','JUDAS_BOUNDARY_DISCARD_FIRST_JOINT_SEEDS','JUDAS_BOUNDARY_ORACLE_FIRST_SOLVE','JUDAS_BOUNDARY_ORACLE_ALL_SOLVES','JUDAS_DIAGNOSTIC_CONTINUE_WRITE','JUDAS_TEST_SCRIPT')){[Environment]::SetEnvironmentVariable($n,$null,'Process')}
$runs=@();foreach($r in $c.runs){$name='m78-closure-'+$r.id;if(Test-Path "$o\$name.json"){throw 'Preserve earlier run'}
 if($r.copyExactColdFrom){$dest=$r.arguments[0];if(Test-Path $dest){throw 'Preserve original exact fixture'};if((Get-FileHash "$($r.copyExactColdFrom)\slots\m77.save").Hash.ToLower() -ne $r.expectedSaveSHA256){throw 'Legacy snapshot input changed'};New-Item -ItemType Directory $dest|Out-Null;Copy-Item "$($r.copyExactColdFrom)\project","$($r.copyExactColdFrom)\slots" $dest -Recurse;if((Get-FileHash "$dest\slots\m77.save").Hash.ToLower() -ne $r.expectedSaveSHA256){throw 'Exact copied fixture mismatch'}}
 $options=@{FilePath=$exe;WorkingDirectory="$root\Source";PassThru=$true;RedirectStandardOutput="$o\$name.stdout.log";RedirectStandardError="$o\$name.stderr.log"};if($r.arguments.Count){$options.ArgumentList=@($r.arguments)};$w=[Diagnostics.Stopwatch]::StartNew();$p=Start-Process @options;[void]$p.Handle;if(!$p.WaitForExit(600000)){Stop-Process -Id $p.Id -Force;$exit='owned case exceeded bounded deadline'}else{$p.Refresh();$exit=$p.ExitCode};$w.Stop();$p.Dispose();$files=@()
 if($r.arguments.Count -and (Test-Path $r.arguments[0] -PathType Container)){$dest=$r.arguments[0];foreach($f in @(Get-ChildItem $dest -File|Where-Object {$_.Extension -in '.json','.jsonl'})+@(Get-ChildItem "$dest\slots" -File -ErrorAction SilentlyContinue)){$report="$name-$($f.Name)";Upload $f.FullName $report;$files+=@{path=$f.FullName;reportName=$report;sha256=(Get-FileHash $f.FullName).Hash.ToLower();bytes=$f.Length}}}
 $row=@{scope=$m.scope;case=$CaseId;run=$r.id;exitCode=$exit;expectedExitCode=$r.expectedExitCode;seconds=$w.Elapsed.TotalSeconds;arguments=@($r.arguments);executableSHA256=(Get-FileHash $exe).Hash.ToLower();archive=$engine.archive;objects=$engine.objects;files=$files;freeBytes=(Get-PSDrive C).Free};$runs+=$row;$rp="$o\$name.json";$row|ConvertTo-Json -Depth 7|Set-Content $rp -Encoding UTF8;Upload "$o\$name.stdout.log" "$name.stdout.log";Upload "$o\$name.stderr.log" "$name.stderr.log";Upload $rp "$name.json"
}
$all=@($exe)+$objs;$files=@();foreach($p in $all){$files+=@{path=$p;name=[IO.Path]::GetFileName($p);bytes=(Get-Item $p).Length;sha256=(Get-FileHash $p).Hash.ToLower()};Upload $p ('m78-closure-'+$CaseId+'-'+[IO.Path]::GetFileName($p)+'.bin')}
$rp="$o\m78-closure-$CaseId-build.json";@{scope=$m.scope;case=$CaseId;reusedOrFreshInputs=$rows;archive=$engine.archive;replacementObjects=$engine.objects;executable=$exe;executableSHA256=(Get-FileHash $exe).Hash.ToLower();executableBytes=(Get-Item $exe).Length;linkerResponse=$link;mapSHA256=$(if(!$OmitMap){(Get-FileHash $map).Hash.ToLower()}else{$null});diagnosticMapOmittedForBoundedStorage=[bool]$OmitMap;frozenReplacedMembersNotExtracted=$true;runs=$runs;generatedFiles=$files;ownedLargeEvidence=@($(if(!$OmitMap){$map}),$log)|Where-Object {$_}|ForEach-Object {@{path=$_;name=[IO.Path]::GetFileName($_);bytes=(Get-Item $_).Length;sha256=(Get-FileHash $_).Hash.ToLower()}};freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 8|Set-Content $rp -Encoding UTF8;Upload $rp ([IO.Path]::GetFileName($rp))
}catch{if(!$m){$o="$root\M78ClosureResults"};New-Item -ItemType Directory $o -Force|Out-Null;$_|Out-String|Set-Content "$o\m78-closure-$CaseId-error.txt";Upload "$o\m78-closure-$CaseId-error.txt" "m78-closure-$CaseId-error.txt";exit 1}
